#[test]
fn automatic_early_quota_survives_typed_execution_and_public_payload() {
    use clearra_host_contract::ProductResultPayloadContent;
    let mut source = String::from("clearra recovery boundary --initial-board-mask 0 --stage-one-board-mask 0xf --target-board-mask 0xc03f --height 4 --queue IOT --stage-one-count 1 --no-hold");
    for suffix in ["", " --max-early-placements auto"] {
        let request = CliCommandParser::parse(&format!("{source}{suffix}")).unwrap().to_app_request().unwrap();
        let AppCommand::BoundaryRecovery(command) = request.command() else { panic!("typed boundary"); };
        assert_eq!(command.query().max_early_placements, None);
        assert_eq!(command.query().effective_max_early_placements(), 2);
        let response = AppContext::default().run(request);
        assert_eq!(response.status(), AppStatus::Success, "{response:?}");
        let host = response.to_host_response();
        let ProductResultPayloadContent::BoundaryRecovery(payload) = host.product_result_payload().unwrap().content() else { panic!("boundary payload"); };
        assert_eq!(payload.early_placement_limit_mode.as_deref(), Some("auto"));
        assert_eq!(payload.max_early_placements, 2);
    }
    source.push_str(" --max-early-placements auto --borrow-role-position 2 --borrow-placement-mask 0xc03");
    assert!(CliCommandParser::parse(&source).is_err(), "Auto cannot falsely describe a selected single-role scope");
}

/// Resolves Auto using only the finite declared role set. A completed role
/// cannot be filled twice, so this structural maximum removes no path.
/// Validation must precede execution; saturating subtraction keeps draft
/// reporting safe without accepting an invalid stage boundary.
pub fn effective_max_early_placements(&self) -> u8 {
    self.max_early_placements.unwrap_or_else(|| {
        self.placement_horizon().saturating_sub(self.stage_one_queue_len)
            .min(MAX_BOUNDARY_QUEUE_PIECES) as u8
    })
}

#[test]
fn automatic_early_count_matches_the_union_of_all_explicit_quotas() {
    for required in [2, 3] {
        for terminal_auto in [false, true] {
            let mut query = tower(required);
            if terminal_auto { query.required_placements = None; }
            let mut explicit_success = false;
            for cap in 0..=required {
                query.max_early_placements = Some(cap as u8);
                let result = query.search(&ExecutionControl::default()).unwrap();
                let success = matches!(result.status, BoundaryRecoveryStatus::Normal
                    | BoundaryRecoveryStatus::PcPreservingRecovery | BoundaryRecoveryStatus::NonPcRecovery);
                explicit_success |= success;
                if success { assert_witness(&query, &result); }
            }
            query.max_early_placements = None;
            let automatic = query.search(&ExecutionControl::default()).unwrap();
            assert_eq!(explicit_success, !matches!(automatic.status, BoundaryRecoveryStatus::NoPath));
            assert_eq!(automatic.borrowed_stage_two_count, required);
            assert_witness(&query, &automatic);
            // The maximum structural quota and Auto invoke exactly the same
            // recovery search; there are no hidden 1,2,... capped reruns.
            query.max_early_placements = Some(required as u8);
            assert_eq!(query.search(&ExecutionControl::default()).unwrap(), automatic);
        }
    }
}

#[test]
fn automatic_limits_do_not_weaken_b2b_or_refund_deleted_early_cells() {
    let mut query = tower(2);
    query.height = 6;
    query.initial_board = mask((0..4).fold(0, |board, row| board | (0x3fc_u64 << (10 * row))));
    query.stage_one_target = mask(0xf);
    query.final_board = mask(0xf);
    query.queue = vec![PieceKind::O, PieceKind::O, PieceKind::I];
    query.placement_role_pieces = vec![PieceKind::I, PieceKind::O, PieceKind::O];
    query.placement_role_masks = vec![mask(0xf), mask(0xc03), mask(0xc03)];
    query.max_early_placements = None;
    let result = query.search(&ExecutionControl::default()).unwrap();
    assert_witness(&query, &result);
    assert_eq!(result.borrowed_stage_two_count, 2);
    assert_eq!(result.steps[..2].iter().map(|step| step.cleared_lines).sum::<u8>(), 4);
    query.preserve_b2b_by_stage = [true, true];
    // The first O's ordinary double is still a breaking actual edge.
    assert_eq!(query.search(&ExecutionControl::default()).unwrap().status, BoundaryRecoveryStatus::NoPath);
}

#[test]
fn automatic_mode_keeps_failure_cancellation_and_selected_scope_distinct() {
    let mut query = tower(2);
    query.max_early_placements = None;
    query.max_states = Some(1);
    assert_eq!(query.search(&ExecutionControl::default()).unwrap().status, BoundaryRecoveryStatus::Incomplete);
    query.max_states = None;
    let token = clearra_core_domain::execution_cancellation::ExecutionCancellationToken::new();
    token.handle().cancel();
    assert_eq!(query.search(&ExecutionControl::new(token)), Err(BoundaryRecoveryError::Cancelled));
    query.early_placement = EarlyPlacementPolicy::SelectedRole { index: 1, placement: query.placement_role_masks[1] };
    assert_eq!(query.search(&ExecutionControl::default()), Err(BoundaryRecoveryError::InvalidBorrowRole));
}

#[test]
fn factorized_pattern_above_old_cutoff_reaches_cancellation_not_invalid_pattern() {
    let bag = vec![PieceKind::I, PieceKind::J, PieceKind::L, PieceKind::O,
        PieceKind::S, PieceKind::T, PieceKind::Z];
    let query = BoundaryRecoveryPatternQuery {
        reference: BoundaryRecoveryQuery {
            initial_board: Board256Mask::EMPTY, stage_one_target: Board256Mask::EMPTY,
            final_board: Board256Mask::EMPTY, height: 8,
            queue: bag.iter().chain(&bag).copied().collect(),
            stage_one_queue_len: 7, required_placements: Some(14),
            placement_role_masks: vec![Board256Mask::from_words([0xf, 0, 0, 0]); 14],
            placement_role_pieces: Vec::new(), max_early_placements: None,
            early_placement: crate::EarlyPlacementPolicy::AnyStageTwoRole,
            hold_enabled: true, rule_profile: RuleProfileId::SrsPlus,
            spin_profile: SpinProfileId::AllSpinPlus, preserve_b2b_by_stage: [false; 2],
            preserve_b2b_bag_mask: 0, initial_b2b: true, max_states: None,
        },
        queue_pattern: "P7P7".into(), max_pattern_evaluations: None, max_total_states: None,
    };
    let expression = QueuePatternExpression::parse("P7P7", 0).unwrap();
    assert!(expression.is_factorized());
    assert_eq!(expression.pattern_count(), 25_401_600);
    let token = ExecutionCancellationToken::new();
    token.handle().cancel();
    // Parsing uses the canonical factorized representation, without eagerly
    // allocating 25 million sequences or silently retaining only 100,000.
    assert_eq!(query.search(&ExecutionControl::new(token)).unwrap_err(),
        BoundaryRecoveryPatternError::Population(BoundaryRecoveryPopulationError::Cancelled));
}

